"use strict";

const prettier = require("prettier-local");
const fooPlugin = require("../plugins/defaultOptions/plugin.js");

test("typescript parser should format Jest inline snapshots", () => {
  const input = `expect(value).toMatchInlineSnapshot(\`snapshot\`);`;
  expect(prettier.format(input, { parser: "typescript" })).toBe(
    "expect(value).toMatchInlineSnapshot(`snapshot`);\n"
  );
});

test("typescript parser can be called without options", () => {
  const typescriptParser =
    require("../../../src/language-js/parse/typescript.js").parsers.typescript;
  const ast = typescriptParser.parse(
    "expect(value).toMatchInlineSnapshot(`snapshot`);"
  );
  expect(ast.type).toBe("Program");
});

